class Solution:
    def finalString(self, s: str) -> str:
        from collections import deque
        d = deque()
        rev = False
        for c in s:
            if c == 'i':
                rev = not rev
            elif rev:
                d.appendleft(c)
            else:
                d.append(c)
        res = ''.join(d)
        return res[::-1] if rev else res

