class Solution {
public:
    string finalString(string s) {
        deque<char> d;
        bool rev = false;
        for (char c : s) {
            if (c == 'i') rev = !rev;
            else if (rev) d.push_front(c);
            else d.push_back(c);
        }
        string res(d.begin(), d.end());
        if (rev) reverse(res.begin(), res.end());
        return res;
    }
};

