class Solution {
    public String finalString(String s) {
        Deque<Character> d = new ArrayDeque<>();
        boolean rev = false;
        for (char c : s.toCharArray()) {
            if (c == 'i') rev = !rev;
            else if (rev) d.addFirst(c);
            else d.addLast(c);
        }
        StringBuilder sb = new StringBuilder();
        for (char c : d) sb.append(c);
        if (rev) sb.reverse();
        return sb.toString();
    }
}

