var finalString = function(s) {
    const d = [];
    let rev = false;
    for (const c of s) {
        if (c === 'i') rev = !rev;
        else if (rev) d.unshift(c);
        else d.push(c);
    }
    let res = d.join('');
    return rev ? res.split('').reverse().join('') : res;
};

